SELECT * FROM customer_histories
WHERE customer_id = #{customerId}
ORDER BY visit_date DESC, created_at DESC

SELECT * FROM customer_histories
WHERE business_id = #{businessId}
ORDER BY visit_date DESC, created_at DESC

SELECT * FROM customer_histories
WHERE customer_id = #{customerId}

    AND visit_date >= #{startDate}


    AND visit_date <= #{endDate}

ORDER BY visit_date DESC

SELECT EXISTS(
    SELECT 1 FROM customer_histories WHERE id = #{id}
)

SELECT EXISTS(
    SELECT 1 FROM customer_histories
    WHERE business_id = #{businessId} AND id = #{id}
)
